#!/usr/bin/env python3
import requests
import concurrent.futures
import time
import sys

# GitLab configuration
GITLAB_URL = "http://the-agent-company.com:8929"
PRIVATE_TOKEN = ""  # Will be obtained after login

def get_projects():
    """Get all projects from GitLab"""
    headers = {"PRIVATE-TOKEN": PRIVATE_TOKEN}
    response = requests.get(f"{GITLAB_URL}/api/v4/projects", headers=headers)
    response.raise_for_status()
    return response.json()

def get_issues(project_id):
    """Get all issues for a project"""
    headers = {"PRIVATE-TOKEN": PRIVATE_TOKEN}
    issues = []
    page = 1

    while True:
        response = requests.get(
            f"{GITLAB_URL}/api/v4/projects/{project_id}/issues",
            headers=headers,
            params={"page": page, "per_page": 100}
        )
        response.raise_for_status()

        page_issues = response.json()
        if not page_issues:
            break

        issues.extend(page_issues)
        page += 1

        # Rate limiting
        time.sleep(0.1)

    return issues

def delete_issue(project_id, issue_iid):
    """Delete a single issue"""
    headers = {"PRIVATE-TOKEN": PRIVATE_TOKEN}
    try:
        response = requests.delete(
            f"{GITLAB_URL}/api/v4/projects/{project_id}/issues/{issue_iid}",
            headers=headers
        )
        if response.status_code == 204:
            return True
        else:
            print(f"Failed to delete issue {issue_iid} from project {project_id}: {response.status_code}")
            return False
    except Exception as e:
        print(f"Error deleting issue {issue_iid} from project {project_id}: {e}")
        return False

def delete_project_issues(project):
    """Delete all issues from a single project using concurrent deletion"""
    project_id = project['id']
    project_name = project['name']

    try:
        issues = get_issues(project_id)
        if not issues:
            print(f"Project '{project_name}' has no issues to delete")
            return 0

        print(f"Deleting {len(issues)} issues from project '{project_name}'...")

        # Use concurrent deletion with 10 workers
        deleted_count = 0
        with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
            # Submit all deletion tasks
            future_to_issue = {
                executor.submit(delete_issue, project_id, issue['iid']): issue['iid'] 
                for issue in issues
            }

            # Process results as they complete
            for future in concurrent.futures.as_completed(future_to_issue):
                issue_iid = future_to_issue[future]
                try:
                    if future.result():
                        deleted_count += 1
                        if deleted_count % 10 == 0:
                            print(f"  Progress: {deleted_count}/{len(issues)} issues deleted from '{project_name}'")
                except Exception as e:
                    print(f"Exception deleting issue {issue_iid}: {e}")

        print(f"Successfully deleted {deleted_count}/{len(issues)} issues from project '{project_name}'")
        return deleted_count

    except Exception as e:
        print(f"Error processing project '{project_name}': {e}")
        return 0

def main():
    print("GitLab Fast Issue Deletion Tool")
    print("===============================")
    print("This tool uses concurrent deletion (10 workers) for maximum speed")

    # Get token from user
    global PRIVATE_TOKEN
    PRIVATE_TOKEN = input("Enter your GitLab personal access token: ").strip()

    try:
        projects = get_projects()
        print(f"\nFound {len(projects)} projects")

        total_deleted = 0
        for project in projects:
            deleted = delete_project_issues(project)
            total_deleted += deleted

            # Small delay between projects to avoid overwhelming the server
            time.sleep(1)

        print(f"\nDeletion completed! Total issues deleted: {total_deleted}")

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
"}

